16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.AgeBand;
20	import org.springframework.samples.petclinic.util.CityLocality;
21	import org.springframework.samples.petclinic.util.CustomerCode;
22	import org.springframework.samples.petclinic.util.E164PhoneNumber;
23	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
24	
25	import jakarta.persistence.*;
26	import jakarta.validation.constraints.NotEmpty;
27	import jakarta.validation.constraints.Pattern;
28	
29	import java.time.LocalDate;
30	import java.time.temporal.ChronoUnit;
31	import java.util.*;
32	
33	/**
34	 * Simple JavaBean domain object representing an owner.
35	 *
36	 * @author Ken Krebs
37	 * @author Juergen Hoeller
38	 * @author Sam Brannen
39	 * @author Michael Isvy
40	 */
41	@Entity
42	@Table(name = "owners")
43	public class Owner extends Person {
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "city")
49	    @NotEmpty
50	    private String city;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    private String email;
59	
60	    @Column(name = "postcode")
61	    private String postcode;
62	
63	    @Column(name = "registration_date")
64	    private LocalDate registrationDate;
65	
66	    @Column(name = "birth_date")
67	    private LocalDate birthDate;
68	
69	    @Column(name = "customer_code")
70	    private String customerCode;
71	
72	    @Column(name = "household_id")
73	    private String householdId;
74	
75	    @Column(name = "namesake_count")
76	    private Integer namesakeCount;
77	
78	    @Column(name = "household_size")
79	    private Integer householdSize;
80	
81	    @Column(name = "membership_number")
82	    private String membershipNumber;
83	
84	    @Column(name = "bulk_signup_warning", nullable = false)
85	    private boolean bulkSignupWarning;
86	
87	    @Column(name = "possible_duplicate", nullable = false)
88	    private boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
94	    private Set<Pet> pets;
95	
96	    public String getAddress() {
97	        return this.address;
98	    }
99	
100	    public void setAddress(String address) {
101	        this.address = address;
102	    }
103	
104	    public String getCity() {
105	        return this.city;
106	    }
107	
108	    public void setCity(String city) {
109	        this.city = city;
110	    }
111	
112	    public String getTelephone() {
113	        return this.telephone;
114	    }
115	
116	    public void setTelephone(String telephone) {
117	        this.telephone = telephone;
118	    }
119	
120	    /**
121	     * The stored E.164 telephone formatted for humans: the country code, a space, then the
122	     * national digits grouped in threes (e.g. {@code "+61 412 345 678"}), while
123	     * {@link #getTelephone()} keeps the raw E.164 form. Derived from stored state, never
124	     * persisted.
125	     */
126	    public String getTelephoneDisplay() {
127	        return E164PhoneNumber.toDisplay(this.telephone);
128	    }
129	
130	    public String getEmail() {
131	        return this.email;
132	    }
133	
134	    public void setEmail(String email) {
135	        this.email = email;
136	    }
137	
138	    /**
139	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
140	     * against the city's region and then stored verbatim. Optional, so may be null.
141	     */
142	    public String getPostcode() {
143	        return this.postcode;
144	    }
145	
146	    public void setPostcode(String postcode) {
147	        this.postcode = postcode;
148	    }
149	
150	    public LocalDate getRegistrationDate() {
151	        return this.registrationDate;
152	    }
153	
154	    public void setRegistrationDate(LocalDate registrationDate) {
155	        this.registrationDate = registrationDate;
156	    }
157	
158	    /**
159	     * The owner's date of birth. Optional, so may be null.
160	     */
161	    public LocalDate getBirthDate() {
162	        return this.birthDate;
163	    }
164	
165	    public void setBirthDate(LocalDate birthDate) {
166	        this.birthDate = birthDate;
167	    }
168	
169	    /**
170	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
171	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
172	     * birth date against the registration date. Null when no birth date is recorded.
173	     * Derived from stored state, never persisted.
174	     */
175	    public String getAgeBand() {
176	        if (this.birthDate == null || this.registrationDate == null) {
177	            return null;
178	        }
179	        return AgeBand.of(this.birthDate, this.registrationDate);
180	    }
181	
182	    public String getCustomerCode() {
183	        return this.customerCode;
184	    }
185	
186	    public void setCustomerCode(String customerCode) {
187	        this.customerCode = customerCode;
188	    }
189	
190	    /**
191	     * The stable identifier of the household this owner belongs to: the first twelve hex
192	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
193	     * sharing a last name and postcode resolves to the same value. Null when the owner has
194	     * no postcode. Assigned at creation.
195	     */
196	    public String getHouseholdId() {
197	        return this.householdId;
198	    }
199	
200	    public void setHouseholdId(String householdId) {
201	        this.householdId = householdId;
202	    }
203	
204	    public Integer getNamesakeCount() {
205	        return this.namesakeCount;
206	    }
207	
208	    public void setNamesakeCount(Integer namesakeCount) {
209	        this.namesakeCount = namesakeCount;
210	    }
211	
212	    public Integer getHouseholdSize() {
213	        return this.householdSize;
214	    }
215	
216	    public void setHouseholdSize(Integer householdSize) {
217	        this.householdSize = householdSize;
218	    }
219	
220	    public String getMembershipNumber() {
221	        return this.membershipNumber;
222	    }
223	
224	    public void setMembershipNumber(String membershipNumber) {
225	        this.membershipNumber = membershipNumber;
226	    }
227	
228	    /**
229	     * Whether this owner was created as part of a bulk signup: {@code true} when more
230	     * than 80 owners had already been registered on this owner's registration date at
231	     * the moment it was created, {@code false} otherwise. Captured at creation.
232	     */
233	    public boolean isBulkSignupWarning() {
234	        return this.bulkSignupWarning;
235	    }
236	
237	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
238	        this.bulkSignupWarning = bulkSignupWarning;
239	    }
240	
241	    /**
242	     * Whether this owner resembles an existing one: {@code true} when, at creation, it
243	     * shared an existing owner's household (same last name and postcode, hence the same
244	     * {@link #getHouseholdId() household id}) while having a different telephone and was not
245	     * a declared household member, {@code false} otherwise. A declared member (created with
246	     * {@code sharesHousehold}) is a genuine member, not a suspected duplicate. When true,
247	     * {@link #getPossibleDuplicateOf()} holds that owner's id. Captured at creation.
248	     */
249	    public boolean isPossibleDuplicate() {
250	        return this.possibleDuplicate;
251	    }
252	
253	    public void setPossibleDuplicate(boolean possibleDuplicate) {
254	        this.possibleDuplicate = possibleDuplicate;
255	    }
256	
257	    /**
258	     * The id of the existing owner this owner possibly duplicates (same household — last
259	     * name and postcode — different telephone), or null when it is not a possible
260	     * duplicate. Captured at creation.
261	     */
262	    public Integer getPossibleDuplicateOf() {
263	        return this.possibleDuplicateOf;
264	    }
265	
266	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
267	        this.possibleDuplicateOf = possibleDuplicateOf;
268	    }
269	
270	    /**
271	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
272	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
273	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
274	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
275	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
276	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
277	     * region is derived directly from the stored postcode and city. Derived from stored
278	     * state, never persisted.
279	     */
280	    public String getLocality() {
281	        String region = CustomerCode.regionOf(this.customerCode);
282	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
283	    }
284	
285	    /**
286	     * The owner's membership level, from 1 to 4: starts at 1, gains 1 when this owner has
287	     * an email address, gains 1 when this owner had no namesakes at creation
288	     * ({@code namesakeCount} is 0), and gains 1 when this owner's tenure exceeds 365 days.
289	     * A newly created owner has zero tenure, so it never exceeds level 3. Capped at 4.
290	     * Derived from stored state, never persisted.
291	     */
292	    public int getMembershipLevel() {
293	        int level = 1;
294	        if (hasEmail()) {
295	            level++;
296	        }
297	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
298	            level++;
299	        }
300	        if (getTenureDays() > 365) {
301	            level++;
302	        }
303	        return Math.min(level, 4);
304	    }
305	
306	    /**
307	     * The owner's tenure in whole days: the number of days from the {@code registrationDate}
308	     * to the current server date, or 0 when no registration date is recorded. Never negative
309	     * in practice, since a future registration date is rejected at creation.
310	     */
311	    private long getTenureDays() {
312	        if (this.registrationDate == null) {
313	            return 0;
314	        }
315	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
316	    }
317	
318	    /**
319	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
320	     * the {@code customerCode}. Derived from stored state, never persisted.
321	     */
322	    public int getCheckDigit() {
323	        return LuhnCheckDigit.of(this.customerCode);
324	    }
325	
326	    /**
327	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
328	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
329	     */
330	    public String getContactPreference() {
331	        return hasEmail() ? "EMAIL" : "PHONE";
332	    }
333	
334	    /**
335	     * The owner's identity key: a composite fingerprint formed as the normalized telephone,
336	     * the email (or empty when absent) and the household id (or empty when none), joined by
337	     * {@code '|'}. Derived from stored state, never persisted.
338	     */
339	    public String getIdentityKey() {
340	        String emailPart = hasEmail() ? this.email : "";
341	        String householdPart = this.householdId == null ? "" : this.householdId;
342	        return this.telephone + "|" + emailPart + "|" + householdPart;
343	    }
344	
345	    private boolean hasEmail() {
346	        return this.email != null && !this.email.isEmpty();
347	    }
348	
349	    protected Set<Pet> getPetsInternal() {
350	        if (this.pets == null) {
351	            this.pets = new HashSet<>();
352	        }
353	        return this.pets;
354	    }
355	
356	    protected void setPetsInternal(Set<Pet> pets) {
357	        this.pets = pets;
358	    }
359	
360	    public List<Pet> getPets() {
361	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
362	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
363	        return Collections.unmodifiableList(sortedPets);
364	    }
365	
366	    public void setPets(List<Pet> pets) {
367	        this.pets = new HashSet<>(pets);
368	    }
369	
370	    public void addPet(Pet pet) {
371	        getPetsInternal().add(pet);
372	        pet.setOwner(this);
373	    }
374	
375	    /**
376	     * Return the Pet with the given name, or null if none found for this Owner.
377	     *
378	     * @param name to test
379	     * @return true if pet name is already in use
380	     */
381	    public Pet getPet(String name) {
382	        return getPet(name, false);
383	    }
384	
385	    /**
386	     * Return the Pet with the given name, or null if none found for this Owner.
387	     *
388	     * @param name to test
389	     * @return true if pet name is already in use
390	     */
391	    public Pet getPet(String name, boolean ignoreNew) {
392	        name = name.toLowerCase();
393	        for (Pet pet : getPetsInternal()) {
394	            if (!ignoreNew || !pet.isNew()) {
395	                String compName = pet.getName();
396	                compName = compName.toLowerCase();
397	                if (compName.equals(name)) {
398	                    return pet;
399	                }
400	            }
401	        }
402	        return null;
403	    }
404	
405	    public Pet getPet(Integer petId) {
406	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
407	    }
408	
409	    @Override
410	    public String toString() {
411	        return new ToStringCreator(this)
412	
413	            .append("id", this.getId())
414	            .append("new", this.isNew())
415	            .append("lastName", this.getLastName())
416	            .append("firstName", this.getFirstName())
417	            .append("address", this.address)
418	            .append("city", this.city)
419	            .append("telephone", this.telephone)
420	            .toString();
421	    }
422	}
